/// <summary>
/// The <c>AVAWHSASNItemRegistratorCls_Extension</c> represents a extension of the class WhsASNItemRegistrator
/// </summary>
[
    ExtensionOf(classStr(WhsASNItemRegistrator))
]
final class AVAWHSASNItemRegistratorCls_Extension
{

}

Method.Source:
/// <summary>
/// Eytension Methode forlicensePlateToRegister
/// </summary>
/// <param name = "_locStructure">
/// The to register WHSUOMStructure
/// </param>
/// <returns>
/// Return the license plate to find the receipt
/// </returns>
protected WHSLicensePlateId licensePlateToRegister(WHSUOMStructure _locStructure)
{
    WHSLicensePlateId               avaLicensePlateToRegister;
    AVARegisterASNItemsIDisposable  avaRegisterASNItemsIDisposable;

    avaLicensePlateToRegister       = next licensePlateToRegister(_locStructure);
    avaRegisterASNItemsIDisposable  = AVARegisterASNItemsIDisposable::current();

    if (avaRegisterASNItemsIDisposable
     && avaRegisterASNItemsIDisposable.aktiveProcess == NoYes::Yes)
    {
        if (_locStructure.Module == WHSModule::Transfer
        && _locStructure.ShipmentId)
        {
            avaRegisterASNItemsIDisposable.addLicensePlateToRegister(avaLicensePlateToRegister, this.avalicensePlateForReceiving(_locStructure, avaLicensePlateToRegister));
        }
    }

    return avaLicensePlateToRegister;
}

/// <summary>
/// Extension MEthode for registerASNItems
/// </summary>
public void registerASNItems()
{
    using (AVARegisterASNItemsIDisposable instance = AVARegisterASNItemsIDisposable::construct())
    {
        instance.aktiveProcess = WHSParameters::find().AVARegisterOutboundSortContainer;

        next registerASNItems();
    }
}

/// <summary>
/// Method to get the transaction license plate for the container license plate
/// </summary>
/// <param name = "_locStructure">
/// The WHSUOMStructure record to regsiter
/// </param>
/// <param name = "_licensePlateToRegister">
/// The default retrun register license Plate
/// </param>
/// <returns>
/// The psotetd outbound sort license plate or the default license plate
/// </returns>
public WHSLicensePlateId avalicensePlateForReceiving(WHSUOMStructure    _locStructure,
                                                     WHSLicensePlateId  _licensePlateToRegister)
{
    WHSLicensePlateId               avaLicensePlateForReceiving;
    WHSOutboundSortPosition         avaOutboundSortPosition;
    WHSOutboundSortPositionTrans    avaOutboundSortPositionTrans;
    WHSASNItem                      avaASNItem;

    select firstonly avaOutboundSortPosition
        exists join avaOutboundSortPositionTrans
        where avaOutboundSortPositionTrans.OutboundSortPosition == avaOutboundSortPosition.RecId
           && avaOutboundSortPositionTrans.SortIdentifier       == _locStructure.LicensePlateId
            join avaASNItem
                where avaASNItem.LoadLineRefRecId   == avaOutboundSortPositionTrans.LoadLine
                   && avaASNItem.LicensePlateId     == avaOutboundSortPositionTrans.SortIdentifier
                   && avaASNItem.ShipmentId         == _locStructure.ShipmentId
                   && avaASNItem.Module             == _locStructure.Module;


    if (avaOutboundSortPosition
     && avaOutboundSortPosition.LicensePlateId != _licensePlateToRegister)
    {
        avaLicensePlateForReceiving = avaOutboundSortPosition.LicensePlateId;
    }
    else
    {
        avaLicensePlateForReceiving = _licensePlateToRegister;
    }

    return avaLicensePlateForReceiving;
}
